// GEO1 (Florida B.E.S.T. Geometry) assignments — one per topic, 10 questions
// in 4 sections: Knowledge & Understanding (3), Application (3), Thinking (2),
// Application (2).
// Imported by scripts/seed-flgeo-assignments.mjs (assignments table only).

const A4 = (code, topic, knowledge, application, thinking, application2) => {
  let n = 0;
  const sec = (arr) => arr.map((q) => `${++n}. ${q}`);
  const description = [
    "Knowledge & Understanding", ...sec(knowledge),
    "Application", ...sec(application),
    "Thinking", ...sec(thinking),
    "Application", ...sec(application2),
  ].join("\n");
  return { title: `Assignment ${code} — ${topic}`, description };
};

